import {tryOnScopeDispose} from '@vueuse/core'

const wsUrl = 'wss://play.rust-lang.org/websocket'
const payloadType = {
  connected: 'websocket/connected',
  request: 'output/execute/wsExecuteRequest',
  execute: {
    begin: 'output/execute/wsExecuteBegin',
    stderr: 'output/execute/wsExecuteStderr',
    stdout: 'output/execute/wsExecuteStdout',
    end: 'output/execute/wsExecuteEnd',
  },
}
let ws = null
let isOpen = false
let uuid = 0

const CONNECT_TIMEOUT = 1e4

function connect() {
  if (isOpen && ws?.readyState === WebSocket.OPEN) return Promise.resolve()
  const socket = new WebSocket(wsUrl)
  ws = socket
  uuid = 0
  socket.addEventListener('close', () => {
    if (ws === socket) {
      ws = null
      isOpen = false
    }
  })
  return new Promise((resolve, reject) => {
    let settled = false
    const timer = setTimeout(() => {
      fail(/* @__PURE__ */ new Error('Rust REPL websocket connection timed out.'))
    }, CONNECT_TIMEOUT)
    function cleanupHandshake() {
      clearTimeout(timer)
      socket.removeEventListener('open', onOpen)
      socket.removeEventListener('message', onMessage)
      socket.removeEventListener('error', onError)
      socket.removeEventListener('close', onClose)
    }
    function succeed() {
      if (settled) return
      settled = true
      cleanupHandshake()
      resolve()
    }
    function fail(error) {
      if (settled) return
      settled = true
      cleanupHandshake()
      if (ws === socket) {
        ws = null
        isOpen = false
      }
      socket.close()
      reject(error)
    }
    function onOpen() {
      isOpen = true
      send(
        payloadType.connected,
        {iAcceptThisIsAnUnsupportedApi: true},
        {
          websocket: true,
          sequenceNumber: uuid,
        },
      )
    }
    function onClose() {
      fail(/* @__PURE__ */ new Error('Rust REPL websocket connection closed.'))
    }
    function onError() {
      fail(/* @__PURE__ */ new Error('Rust REPL websocket connection failed.'))
    }
    function onMessage(e) {
      try {
        if (JSON.parse(e.data).type === payloadType.connected) succeed()
      } catch {}
    }
    socket.addEventListener('open', onOpen)
    socket.addEventListener('message', onMessage)
    socket.addEventListener('error', onError)
    socket.addEventListener('close', onClose)
    tryOnScopeDispose(() => socket.close())
  })
}
function send(type, payload, meta) {
  const msg = {
    type,
    meta,
    payload,
  }
  ws?.send(JSON.stringify(msg))
}
async function rustExecute(code, {onEnd, onError, onStderr, onStdout, onBegin}) {
  await connect()
  if (!ws) throw new Error('Rust REPL websocket is not connected.')
  const socket = ws
  const meta = {sequenceNumber: uuid++}
  const payload = {
    backtrace: false,
    channel: 'stable',
    crateType: 'bin',
    edition: '2021',
    mode: 'release',
    tests: false,
    code,
  }
  let stdout = ''
  let stderr = ''
  await new Promise((resolve, reject) => {
    let settled = false
    function settle(error) {
      if (settled) return
      settled = true
      socket.removeEventListener('message', onMessage)
      socket.removeEventListener('close', onSocketClose)
      socket.removeEventListener('error', onSocketError)
      if (error) reject(error)
      else resolve()
    }
    function onSocketClose() {
      settle(/* @__PURE__ */ new Error('Rust REPL websocket connection closed.'))
    }
    function onSocketError() {
      settle(/* @__PURE__ */ new Error('Rust REPL websocket connection failed.'))
    }
    function onMessage(e) {
      let data
      try {
        data = JSON.parse(e.data)
      } catch {
        return
      }
      const {type, payload, meta: _meta = {}} = data
      if (_meta.sequenceNumber !== meta.sequenceNumber) return
      if (type === payloadType.execute.begin) onBegin?.()
      if (type === payloadType.execute.stdout) {
        stdout += payload
        if (stdout.endsWith('\n')) {
          onStdout?.(stdout)
          stdout = ''
        }
      }
      if (type === payloadType.execute.stderr) {
        stderr += payload
        if (stderr.endsWith('\n')) {
          if (stderr.startsWith('error:')) {
            const index = stderr.indexOf('\n')
            onStderr?.(stderr.slice(0, index))
            onStderr?.(stderr.slice(index + 1))
          } else onStderr?.(stderr)
          stderr = ''
        }
      }
      if (type === payloadType.execute.end) {
        if (payload.success === false) onError?.(payload.exitDetail)
        onEnd?.()
        settle()
      }
    }
    if (socket.readyState !== WebSocket.OPEN) {
      settle(/* @__PURE__ */ new Error('Rust REPL websocket connection closed.'))
      return
    }
    socket.addEventListener('message', onMessage)
    socket.addEventListener('close', onSocketClose)
    socket.addEventListener('error', onSocketError)
    socket.send(
      JSON.stringify({
        type: payloadType.request,
        meta,
        payload,
      }),
    )
  })
}

export {rustExecute}
